"""Compile original cloud case studies, definitions and lab plans into a data pack."""
import json
from pathlib import Path
topics=[]
def topic(core,objective,title,concepts,case,correct,wrong,why,lab):
 domain=int(objective.split('.')[0]);key=f'cert{core}-{objective}';previous=next((t['id'] for t in reversed(topics) if t['core']==core and t['domain']==domain),None)
 names=[x[0] for x in concepts];definitions=[x[1] for x in concepts]
 questions=[dict(id=key+'-recall-'+str(i),prompt='Which concept fits this requirement? '+definitions[i],options=names,answer=i,explanation=names[i]+': '+definitions[i],tier=1) for i in range(len(concepts))]
 questions.append(dict(id=key+'-match',prompt='Match each tool or concept to the requirement it solves.',left=names,options=list(reversed(definitions)),answer=list(reversed(range(len(concepts)))),explanation='\n'.join(n+': '+d for n,d in concepts),tier=2))
 questions.append(dict(id=key+'-case',prompt=case,options=[correct]+wrong,answer=0,explanation=why,tier=3))
 source='https://docs.aws.amazon.com/aws-certification/latest/cloud-practitioner-02/' if core==5 else 'https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900'
 topics.append(dict(id=key,title=title,core=core,objective=objective,domain=domain,type='software' if core==5 else 'security',questions=questions,requires=[previous] if previous else [],lore='CONCEPTS AND BOUNDARIES\n\n'+'\n\n'.join(n+' — '+d for n,d in concepts)+'\n\nAPPLIED DECISION\n\n'+case+'\n\n'+correct+'\n\nWHY THIS FITS\n\n'+why,example=case+' '+correct+' '+why,flow=[names[0],names[1],names[2],names[3]],lab=lab,sources=[dict(title='Official exam guide and further study',url=source)]))

topic(5,'1.1','Cloud value, elasticity and availability',[
 ('Elasticity','Add and remove capacity as demand changes, rather than keeping peak capacity running permanently.'),('Scalability','Support a larger workload by increasing capacity; this alone does not imply automatic scaling down.'),('High availability','Design redundant service paths so a component failure is less likely to interrupt service.'),('Agility','Provision and experiment quickly, with controls for cost, access and cleanup.')],
 'An online shop has a predictable quiet period and short traffic surges. What design directly matches capacity to changing demand?', 'Use measured demand to scale out and scale in within tested limits', ['Buy maximum capacity and never reduce it','Treat a backup alone as live redundancy','Disable monitoring to avoid scaling events'], 'Elasticity needs both growth and reduction. Health checks, limits and testing still matter; cloud use alone does not guarantee availability.', ['Draw the normal and peak request path.','Identify the metric that triggers scaling.','Record a minimum, maximum and cooldown.','Describe a test that verifies scale-in does not drop required work.'])
topic(5,'1.2','Well-Architected tradeoffs',[
 ('Operational excellence','Run workloads with observable, repeatable operations and learning from incidents.'),('Reliability','Recover from disruption and handle changes in demand without abandoning correctness.'),('Cost optimization','Meet required outcomes while avoiding waste and selecting suitable consumption patterns.'),('Security and sustainability','Protect identities and data while reducing unnecessary resource use; neither goal removes reliability requirements.')],
 'A team wants the cheapest possible server but the workload must survive one server failure. What is the best decision process?', 'Compare designs against reliability, security, performance, operating effort, cost and sustainability requirements', ['Choose solely by hourly price','Remove backups because they cost money','Assume the provider guarantees every application'], 'Architecture involves tradeoffs across six pillars, including performance efficiency. A cheaper instance can create a more expensive or unreliable system.', ['List six Well-Architected pillars.','For a small web app, identify one risk per pillar.','Propose a measurable improvement and its tradeoff.','Document who verifies it.'])
topic(5,'1.3','Cloud migration planning',[
 ('Rehost','Move a workload with relatively little architectural change, often called lift-and-shift.'),('Replatform','Make selected platform changes without redesigning the entire application.'),('Refactor','Redesign important application parts to exploit a different architecture.'),('Retain or retire','Keep a workload where it is, or remove it when business and technical evidence support that choice.')],
 'A tightly coupled legacy app has a near-term migration deadline and no tested redesign. What is a reasonable plan?', 'Assess dependencies, choose a feasible migration strategy, test and preserve a rollback plan', ['Rewrite everything during the production cutover','Move data without checking dependencies','Assume every workload must migrate immediately'], 'Migration is a business and technical decision. The AWS Cloud Adoption Framework includes organizational readiness; discovery, data transfer, validation and rollback all affect the plan.', ['Map application, database, identity and network dependencies.','Compare rehost with replatform.','Define data validation and rollback criteria.','Estimate downtime and obtain approval.'])
topic(5,'1.4','Cloud economics and rightsizing',[
 ('Variable consumption','Costs can change with resources used and duration; visibility and controls are needed.'),('Rightsizing','Choose capacity from workload evidence instead of permanently overprovisioning.'),('Total cost of ownership','Include operations, facilities, licensing, migration and data transfer as well as compute prices.'),('Automation','Repeat controlled tasks with less manual effort while retaining approval, audit and recovery safeguards.')],
 'A cloud bill rises even though instance prices did not change. What should the team investigate?', 'Resource usage, sizing, storage, transfer, licenses and operating patterns', ['Only the instance price','Assume every cloud workload is cheaper','Delete all usage records'], 'A unit price does not describe total consumption. Savings claims require comparable assumptions and actual workload evidence.', ['Build a cost inventory without creating resources.','Include storage retention and egress.','Identify an idle-resource cleanup policy.','State what evidence supports a smaller instance.'])
topic(5,'2.1','Shared responsibility by service',[
 ('Security of the cloud','AWS operates underlying facilities and infrastructure within its service responsibilities.'),('Security in the cloud','Customers configure access, protect their data and meet their applicable obligations.'),('EC2 guest management','Customers normally patch and configure the guest OS and applications on their EC2 instances.'),('Managed-service boundary','A managed service shifts selected platform duties to AWS while retaining customer data, identity and configuration duties.')],
 'A company moves from EC2-hosted code to Lambda. Which statement is accurate?', 'AWS manages more server infrastructure, but the company still manages code, permissions and data handling', ['The company no longer has security responsibilities','AWS chooses the application permissions automatically','The company must patch Lambda host servers itself'], 'Shared responsibility changes with the service. Serverless removes server provisioning work, not application ownership.', ['Make a responsibility table for EC2, RDS and Lambda.','Assign host patching, guest patching, IAM and data classification.','Mark duties that change with service selection.','Check the service documentation before finalizing.'])
topic(5,'2.2','Compliance, encryption and evidence',[
 ('AWS Artifact','Obtain available AWS compliance reports and agreements to support a compliance review.'),('Encryption at rest','Protect stored data with appropriate keys and access controls.'),('Encryption in transit','Protect data moving between endpoints using suitable transport security.'),('Customer compliance assessment','Evaluate workload configuration and obligations; a provider report alone does not certify the customer workload.')],
 'An auditor asks whether a customer application is compliant because AWS holds a certification. What is the best response?', 'Use provider evidence alongside a review of customer controls, scope and applicable requirements', ['Declare every workload automatically compliant','Ignore the application configuration','Publish encryption keys as proof'], 'Compliance evidence has a scope. Key access, identity configuration, retention and workload responsibilities remain relevant.', ['Identify a fictional workload data category.','Separate provider evidence from customer evidence.','Map encryption, access and retention controls.','Record unresolved compliance questions.'])
topic(5,'2.3','IAM, roles and account protection',[
 ('IAM role','Grant permissions that can be assumed using temporary credentials, avoiding embedded long-lived secrets.'),('Least privilege','Limit actions and resources to what the workload or person needs.'),('Root-user protection','Protect the powerful account identity with strong authentication and reserve it for tasks that require it.'),('IAM Identity Center','Coordinate workforce access to supported accounts and applications with centralized identity integration.')],
 'Code running on EC2 needs to read one S3 bucket. Which design best limits credential exposure?', 'Use an appropriate role with scoped permissions instead of embedding root keys', ['Put root access keys in the repository','Make the bucket public','Share one administrator password across services'], 'Temporary credentials and a scoped policy reduce exposure. Explicit permissions, trust relationships and testing still determine effective access.', ['Write a plain-language policy for one bucket.','List allowed actions and denied use cases.','Explain role trust versus permissions.','Review where credentials would exist.'])
topic(5,'2.4','Security services and audit signals',[
 ('CloudTrail','Record AWS account activity for investigation and audit.'),('AWS Config','Track supported resource configurations and evaluate configured rules.'),('GuardDuty','Detect suspicious activity using supported data sources and threat detection capabilities.'),('Secrets Manager','Manage supported secrets and rotation workflows rather than hard-coding credentials.')],
 'A team must determine which identity changed an AWS resource yesterday. Which evidence is the best starting point?', 'Review relevant CloudTrail events and correlate the identity, time and resource', ['Use only a pricing estimate','Assume a threat alert proves the full timeline','Rotate a password and delete the logs'], 'CloudTrail supports activity investigation; detection and configuration tools answer related but different questions. Preserve relevant records.', ['Draft a fictional change event with actor, action and time.','Map auditing, configuration and detection to tools.','Explain why one tool cannot answer every question.','Define log access and retention requirements.'])
topic(5,'3.1','Deploying and operating AWS resources',[
 ('Management Console','Use a browser interface for interactive service configuration and inspection.'),('AWS CLI and SDKs','Use programmatic calls for scripts and applications with appropriate authentication.'),('CloudFormation','Declare supported infrastructure for repeatable provisioning and lifecycle management.'),('Hybrid deployment','Connect on-premises and cloud environments while accounting for network, identity and operational dependencies.')],
 'A team repeatedly builds the same environment by hand and finds drift between deployments. What improves repeatability?', 'Version and review an infrastructure template, then test its deployment and rollback', ['Keep manual steps undocumented','Embed administrator secrets in templates','Treat a successful deployment as permanent proof of correctness'], 'Infrastructure as code makes desired configuration reviewable and repeatable. Change control and validation remain necessary.', ['Sketch a template for network, compute and storage.','Identify parameters versus secrets.','Record deployment order and dependencies.','Plan drift detection and rollback.'])
topic(5,'3.2','Regions, zones and edge delivery',[
 ('Region','A geographic AWS area containing multiple Availability Zones.'),('Availability Zone','One or more discrete data centers with independent infrastructure within a Region.'),('Edge location','A location used by supported edge services to bring content or processing closer to users.'),('Multi-Region design','Use more than one Region when requirements justify added replication, cost and operational complexity.')],
 'A service must tolerate one Availability Zone failing, while keeping most traffic within one Region. What is a fitting design?', 'Deploy redundant components across zones and test failover and data behavior', ['Put all copies in one server rack','Assume an edge cache replaces every database','Choose a second Region without considering data consistency'], 'Availability depends on application architecture and dependencies. Multi-zone design reduces a zone failure risk but is not a backup strategy by itself.', ['Draw a two-zone request path.','Mark shared dependencies and possible single points of failure.','Describe how sessions and data survive failover.','Explain when a second Region might be needed.'])
topic(5,'3.3','Compute, containers and elasticity',[
 ('Amazon EC2','Run virtual servers with control over guest OS and instance configuration.'),('AWS Lambda','Run event-driven code without provisioning the underlying servers.'),('ECS and EKS','Orchestrate containers using AWS-native ECS or managed Kubernetes through EKS.'),('Auto Scaling and load balancing','Adjust capacity and distribute traffic to suitable healthy targets as part of an application design.')],
 'A short task runs when a file arrives and should not require an always-running server. Which option should be considered?', 'An event-driven Lambda design, after checking runtime, limits and dependencies', ['Always purchase the largest EC2 instance','Use a load balancer as the code runtime','Assume containers remove all operations work'], 'Service choice follows workload constraints. Fargate is another serverless compute option for supported containers; it differs from Lambda invocation.', ['Compare EC2, Lambda and a container task for a file-processing job.','List control, scaling and runtime constraints.','Map one trigger to one unit of work.','Plan retries and idempotency.'])
topic(5,'3.4','Databases, caches and migration',[
 ('Amazon RDS and Aurora','Use managed relational database options when a relational model and service features fit.'),('DynamoDB','Use managed key-value/document database capabilities for suitable access patterns.'),('ElastiCache','Use a managed in-memory cache to reduce repeated work or support low-latency access patterns.'),('AWS DMS','Support suitable database migration and replication workflows, with validation of compatibility and results.')],
 'An application repeatedly reads the same expensive query result and can tolerate short cache staleness. What can reduce database load?', 'Introduce a suitable cache with an explicit expiry and invalidation strategy', ['Replace database backups with a cache','Assume every query should move to a document store','Disable access controls for faster queries'], 'Caching can reduce repeated reads, but stale data, invalidation and failure behavior must be designed. A cache is not the authoritative recovery copy.', ['Identify an authoritative database and cached values.','Choose a hypothetical expiry.','Describe a cache miss and stale entry.','Plan migration data validation.'])
topic(5,'3.5','VPC networking and connectivity',[
 ('VPC and subnet','Define a logically isolated network and its subnet address ranges and routing boundaries.'),('Security group','Apply stateful traffic rules to associated resources.'),('Route 53 and CloudFront','Provide DNS-related services and content delivery respectively; they solve different parts of a request path.'),('VPN and Direct Connect','Use encrypted network tunnels or dedicated connectivity options according to requirements; dedicated connectivity alone is not a universal encryption guarantee.')],
 'An instance is unreachable although its application is running. What should be reviewed before replacing it?', 'The route, addressing, applicable security rules and required network path', ['Only its display name','Only the monthly bill','Delete the VPC without collecting evidence'], 'Connectivity depends on several layers. Network ACLs are stateless subnet controls, unlike stateful security groups; both can affect the path.', ['Draw a client-to-instance route.','Mark DNS, routes, gateways, security groups and network ACLs.','State the direction and return path.','Compare VPN and dedicated connectivity constraints.'])
topic(5,'3.6','Object, block and file storage',[
 ('Amazon S3','Store objects in buckets with storage class, lifecycle, access and protection options.'),('Amazon EBS','Provide block storage volumes for supported EC2 use cases.'),('Amazon EFS','Provide managed elastic file storage for supported shared-file use cases.'),('Storage lifecycle and backup','Choose retention, retrieval, resilience and recovery controls from access patterns and loss requirements.')],
 'Several Linux application instances need shared file access rather than independent block volumes. Which service category fits?', 'Evaluate shared file storage such as EFS', ['Treat every S3 bucket as a mounted local block disk','Attach one ordinary EBS volume to all instances without checking support','Eliminate backups because storage is managed'], 'Object, block and file interfaces are different. Storage durability, application availability and tested recovery are separate concerns.', ['Classify photos, a boot disk and shared files by interface.','Choose a retention and retrieval requirement.','Explain lifecycle transitions versus backups.','Document recovery testing.'])
topic(5,'3.7','Analytics and AI service selection',[
 ('Amazon Athena','Query suitable data in S3 using SQL without managing a dedicated query server.'),('Amazon Redshift','Use managed data warehouse capabilities for appropriate analytics workloads.'),('Amazon Bedrock','Access supported foundation models through a managed service with model and governance choices.'),('Managed AI services','Choose specialized services such as text, speech or image analysis when their capabilities and data controls fit.')],
 'A team needs occasional SQL analysis of files already stored in S3. Which service should it evaluate first?', 'Athena, checking formats, scan cost and access permissions', ['Always build a new relational application database','Use an identity directory as the analytics engine','Upload confidential files to an unapproved AI endpoint'], 'Service purpose matters more than brand familiarity. Other in-scope services include Glue for data integration and SageMaker AI for machine-learning workflows; validate requirements and current features.', ['Map SQL analysis, warehousing and model inference to service categories.','List privacy and cost questions.','Describe an approved sample-data workflow.','Define how outputs will be verified.'])
topic(5,'3.8','Integration, monitoring and management',[
 ('Amazon SQS','Decouple producers and consumers with queued messages and explicit processing/retry behavior.'),('Amazon SNS','Distribute supported notifications to subscribers using a publish/subscribe pattern.'),('Amazon EventBridge','Route supported events to targets according to configured event rules.'),('Amazon CloudWatch','Collect monitoring telemetry such as metrics and logs and use configured alarms and dashboards.')],
 'A burst of orders overwhelms a worker that can process them gradually. Which architecture helps decouple arrival from processing?', 'Place suitable work items in a queue and design retries and idempotent consumers', ['Drop all orders during bursts','Use a dashboard as durable work storage','Assume publish/subscribe and queues are identical'], 'Queues can buffer work, but delivery behavior, failure handling and consumer design remain important. Monitoring reveals whether the backlog is healthy.', ['Draw producer, queue and worker.','Describe duplicate-delivery handling.','Choose backlog and failure metrics.','Plan poison-message handling.'])
topic(5,'4.1','Purchase models and transfer costs',[
 ('On-Demand','Use eligible compute without a long-term commitment, paying according to its pricing model.'),('Savings Plans and reservations','Evaluate commitments or reservation options for suitable predictable usage; coverage and flexibility differ.'),('Spot','Use interruptible spare compute when the workload can tolerate interruption.'),('Data transfer','Consider movement between services, zones, Regions and the internet; exact charges depend on the path and service.')],
 'A batch job can checkpoint and restart after interruption. Which option may reduce compute cost?', 'Evaluate Spot while planning interruption handling and fallback', ['Assume Spot can never be interrupted','Buy a commitment before measuring the workload','Ignore data-transfer costs'], 'Purchase options trade flexibility, commitment and interruption risk. A low compute price does not account for the whole workload bill.', ['Compare three purchase models for steady, bursty and restartable jobs.','State the assumptions for each.','Trace likely data transfer paths.','Avoid quoting a fixed price without a current calculator.'])
topic(5,'4.2','Billing tools and account organization',[
 ('AWS Pricing Calculator','Estimate proposed service configurations and consumption assumptions.'),('Cost Explorer','Analyze supported cost and usage information over time.'),('AWS Budgets','Set supported budget thresholds and notifications; notifications alone do not universally stop spending.'),('Organizations and cost allocation','Organize accounts and billing visibility using appropriate organizational structure and activated allocation mechanisms.')],
 'Finance needs to see which department caused a cost increase. What should the team investigate?', 'Cost and usage breakdowns, account structure and appropriate cost-allocation tags', ['Assume a budget notification caps every charge','Use only a pre-deployment estimate','Delete billing data after each invoice'], 'Forecasting, reporting and budget alerts have distinct functions. Allocation requires consistent account and tagging practices, not merely an arbitrary label.', ['Create a fictional account and tag map.','Separate estimate, historical report and alert use cases.','Define who responds to a budget alert.','Document how attribution will be checked.'])
topic(5,'4.3','Support, health and trusted guidance',[
 ('AWS documentation and re:Post','Use official technical references and community/knowledge resources, checking context and date.'),('AWS Health','Review relevant service events and account-specific health information where available.'),('Trusted Advisor','Review available checks and recommendations; access and scope depend on the applicable offering.'),('AWS Support and partners','Select available support and professional assistance based on business needs and current plan capabilities.')],
 'A production issue affects a critical service. What is a reasonable first response?', 'Follow the incident process, check relevant health information and use the support channel available to the account', ['Assume every plan has identical response guarantees','Post secrets in a public question','Wait for a community answer without triage'], 'Support offerings change. Check current entitlements and severity guidance; recommendations do not replace tested workload operations.', ['Build a support escalation sheet using no real secrets.','Identify health versus configuration evidence.','List current-plan questions to verify.','Record a safe public-support redaction checklist.'])

topic(6,'1.1','Cloud computing models and responsibility',[
 ('Public cloud','Use provider-operated shared cloud services with logical customer separation.'),('Private cloud','Use a cloud environment dedicated to one organization.'),('Hybrid cloud','Connect distinct private/on-premises and public cloud environments.'),('Consumption and responsibility','Pay according to configured consumption while retaining customer responsibilities appropriate to the service model.')],
 'A business keeps one application in its data center while integrating Azure services. Which model fits?', 'Hybrid cloud with explicit network, identity and data responsibilities', ['SaaS automatically replaces the data center','A public endpoint means no customer security duties','Consumption pricing guarantees a fixed bill'], 'Deployment model and service model are separate choices. Serverless shifts infrastructure operations but does not remove code, access or data obligations.', ['Draw the two environments and their trust boundary.','List shared dependencies.','Assign three customer responsibilities.','Identify variable-cost drivers.'])
topic(6,'1.2','Availability, scalability and cloud benefits',[
 ('High availability','Use redundancy and appropriate design to reduce service interruption.'),('Scalability and elasticity','Increase capacity for growth and adjust it to varying demand where supported.'),('Predictability and reliability','Use evidence, design and recovery planning to meet performance and service expectations.'),('Manageability and governance','Control resources through supported tools, policy, automation and operational visibility.')],
 'A cloud VM is a single point of failure. Which statement is accurate?', 'The application still needs an availability design; cloud placement alone does not make it highly available', ['All cloud VMs automatically survive every outage','Backups guarantee zero downtime','Scaling up a single VM removes every dependency'], 'Redundancy, recovery and scaling solve related but distinct requirements. Security and governance can be benefits when configured deliberately.', ['Draw a single-instance and redundant design.','Identify failure paths and recovery steps.','State a measurable service goal.','Explain one cost/availability tradeoff.'])
topic(6,'1.3','IaaS, PaaS and SaaS choices',[
 ('IaaS','Rent infrastructure such as virtual machines while managing the guest OS and applications.'),('PaaS','Use a managed application platform that removes selected infrastructure and runtime management tasks.'),('SaaS','Use a finished application while managing appropriate identities, settings and data decisions.'),('Service-model tradeoff','Compare customer control, operational effort, compatibility and responsibilities rather than treating one model as universally best.')],
 'A team wants managed web hosting without maintaining the host operating system. What should it consider?', 'A PaaS offering such as Azure App Service, after checking application requirements', ['Only a bare VM can host an application','SaaS means customers ignore permissions','Every service model provides identical control'], 'The useful service model depends on constraints. Reducing platform operations can also reduce low-level control.', ['Build a responsibility matrix for all three service models.','Assign OS patching, application code and identity management.','Choose a model for a small web app.','State a compatibility check.'])
topic(6,'2.1','Azure geography and resource hierarchy',[
 ('Regions and zones','Regions are geographic areas; supported availability zones provide physically separate locations within a region.'),('Resource group','Organize related resources within a subscription for management and lifecycle purposes.'),('Subscription','Provide a billing and management boundary containing resource groups and resources.'),('Management group','Organize subscriptions into a governance hierarchy with inherited controls where applicable.')],
 'An organization must apply governance consistently across many subscriptions. Which structure helps?', 'An appropriate management-group hierarchy with tested policy and access inheritance', ['Put all subscriptions inside a storage container','Treat a region as an access role','Assume deleting one resource group is a harmless rename'], 'Resource hierarchy and geographic placement are different dimensions. Region pairs and sovereign regions address additional resilience and compliance considerations, not automatic universal replication.', ['Draw management group → subscription → resource group → resource.','Add a region label separately.','Describe inherited governance.','Identify the scope of a destructive operation.'])
topic(6,'2.2','Compute, application hosting and networking',[
 ('Azure Virtual Machines','Run guest operating systems and workloads with infrastructure-level configuration choices.'),('App Service and Functions','Use managed web hosting or event-driven code execution according to workload requirements.'),('Virtual Network','Provide network boundaries, subnets and connectivity for supported Azure resources.'),('VPN Gateway and ExpressRoute','Connect environments using supported tunnel or private-connectivity designs with different requirements and tradeoffs.')],
 'An application should be reachable privately from another network, with controlled DNS and routing. What must the design address?', 'Private endpoints or other appropriate private connectivity, DNS, routes and access rules as applicable', ['Only the resource display name','Assume every endpoint is private by default','Disable authentication because a network is private'], 'Compute options include VMs, scale sets and containers; hosting and network choices must fit the workload. Public/private endpoints describe reachability, not a substitute for authorization.', ['Sketch client, DNS, network and application.','Mark public versus private endpoints.','Compare VM, container and function hosting.','Identify one route and one authorization dependency.'])
topic(6,'2.3','Storage, redundancy and migration',[
 ('Blob Storage','Store unstructured objects such as images and archives with suitable access tiers and protection.'),('Azure Files','Provide managed file shares for supported shared-file use cases.'),('Redundancy options','Choose local, zone or geographic replication where supported, based on failure and recovery requirements.'),('Transfer and migration tools','Use tools such as AzCopy, Storage Explorer, Azure File Sync, Azure Migrate or Data Box according to the workload and transfer constraints.')],
 'A team needs to move a large offline dataset and cannot rely on available network bandwidth. Which option deserves evaluation?', 'An appropriate Azure Data Box transfer workflow, checking current availability and requirements', ['Assume a storage tier migrates a server automatically','Disable encryption to make every transfer acceptable','Use a VM snapshot as the only independent backup'], 'Data movement tools have different scopes. Replication is not a complete backup strategy, and tier choice affects access behavior and cost.', ['Classify object and file workloads.','Compare online copy and offline transfer.','Select hypothetical redundancy and recovery requirements.','Describe a post-transfer integrity check.'])
topic(6,'2.4','Identity, access and defense in depth',[
 ('Microsoft Entra ID','Provide cloud identity and authentication capabilities for supported users and applications.'),('Azure RBAC','Authorize actions at an Azure resource scope through role assignments.'),('Conditional Access','Apply supported access policies using identity and contextual signals, with suitable licensing and configuration.'),('Defender for Cloud and Zero Trust','Use security posture/workload protection capabilities as appropriate, alongside explicit verification, least privilege and layered controls.')],
 'A user signs in successfully but cannot manage one resource group. What should be examined?', 'The relevant RBAC assignment, scope and effective permissions, rather than assuming sign-in grants resource control', ['Only the user’s monitor','Remove all authentication policies','Make every account an owner'], 'Authentication and authorization are distinct. Microsoft Entra Domain Services provides managed domain capabilities for compatible needs; it is not interchangeable with every Entra ID feature.', ['Create a fictional principal-role-scope table.','Separate sign-in policy from resource permissions.','Plan an MFA/Conditional Access test with recovery access.','Identify one defense-in-depth layer.'])
topic(6,'3.1','Cost estimation, budgets and tags',[
 ('Pricing calculator','Estimate the cost of a proposed configuration with explicit usage assumptions.'),('Cost Management','Analyze supported spending and usage information and identify trends.'),('Budget alert','Notify responsible people about configured thresholds; an alert alone is not an automatic universal shutdown.'),('Resource tags','Apply consistent metadata to support organization and cost attribution where supported.')],
 'A budget alert fires during a high-usage period. What should the team do next?', 'Investigate the usage and respond through the approved cost-control process', ['Assume all charges stopped','Delete logs to lower the invoice','Treat an estimate as proof of the final bill'], 'Costs can include compute time, storage and transfer. Alerts, forecasts, tagging and action workflows solve different parts of cost management.', ['Write a fictional cost estimate with assumptions.','Define tags and ownership.','Design alert recipients and an escalation path.','Identify what requires approval before stopping resources.'])
topic(6,'3.2','Governance, compliance and locks',[
 ('Azure Policy','Evaluate and enforce supported resource configuration requirements.'),('Resource lock','Help protect against accidental deletion or modification depending on the lock type; it is not a backup.'),('Microsoft Purview','Provide supported data governance, discovery and compliance-related capabilities.'),('Governance boundary','Keep organizational rules, access permissions and legal obligations distinct but coordinated.')],
 'A team must restrict deployment locations and protect a critical resource from accidental deletion. What combination fits?', 'Use appropriate policy for allowed locations and a suitable resource lock, alongside RBAC and recovery controls', ['Use only a tag as enforcement','Grant everyone owner access','Replace every backup with a lock'], 'Policy, locks and permissions are complementary. Authorized users may be able to remove locks; data recovery still needs a tested plan.', ['Map allowed-location policy and delete lock to separate requirements.','State who may change each control.','Describe how an exception is approved.','Record the remaining backup requirement.'])
topic(6,'3.3','Deployment tools, ARM and Azure Arc',[
 ('Azure portal and Cloud Shell','Use supported browser management interfaces and shell tooling with appropriate identity and permissions.'),('Azure CLI and PowerShell','Use command-line interfaces for repeatable administration and scripts.'),('ARM and templates','Manage supported resource deployments with Azure Resource Manager and declarative template approaches.'),('Azure Arc','Extend supported Azure management and governance capabilities to resources outside Azure.')],
 'A team repeatedly builds inconsistent environments by clicking through the portal. What improves reviewability?', 'Version an appropriate infrastructure-as-code definition and validate deployments through change control', ['Store owner passwords inside every template','Skip testing because the file is declarative','Assume Azure Arc physically moves every server into Azure'], 'Management interfaces and desired-state definitions differ. Automation needs scoped credentials, parameter handling, validation and rollback planning.', ['Sketch an ARM-style dependency graph.','Separate configuration from secrets.','Compare portal changes with reviewed templates.','Identify a suitable Arc management use case.'])
topic(6,'3.4','Monitoring, service health and recommendations',[
 ('Azure Monitor','Collect and analyze supported telemetry such as metrics and logs.'),('Log Analytics and Application Insights','Query log data and investigate supported application telemetry respectively.'),('Azure Service Health','Review personalized service issue and maintenance information relevant to subscribed resources.'),('Azure Advisor','Review supported recommendations for improving an Azure environment.')],
 'An app is slow, but there is no confirmed regional incident. What is a reasonable investigation?', 'Use application and infrastructure telemetry, check relevant service health and correlate evidence before choosing a fix', ['Treat every recommendation as proof of the cause','Ignore application traces','Recreate the entire subscription immediately'], 'Metrics, logs, traces, service events and recommendations provide different evidence. Alerts require useful thresholds and an owner who can respond.', ['Choose a latency metric and a useful log query goal.','Separate app evidence from provider service events.','Define an actionable alert.','Record how a proposed fix will be verified.'])

